Ltac stepto n pc := lazymatch n with O => idtac | S ?k => tryif at_stop [pc] then idtac else (awalk1; stepto k pc) end.
(* [comment removed for export] *)
Ltac nfr H :=
  rewrite ?Z.mul_1_r in H; rewrite ?hip_fd0 in H by flia; rewrite ?hipb_fd0 in H by flia;
  rewrite ?Z.add_0_l, ?Z.add_0_r, ?Z.sub_0_r in H; try change (0 mod 18446744073709551616) with 0 in H; rewrite ?Z.add_0_l, ?Z.add_0_r, ?Z.sub_0_r, ?Z.mul_0_l in H;
  repeat (rewrite (bv_swrap_small 32) in H by (change (bv_half_modulus 32) with (2^31); lia)).

